import React, { useEffect, useState } from "react";
import { Outlet, Link, useNavigate, useLocation } from "react-router-dom";
import {
  FaBookOpen,
  FaChalkboardTeacher,
  FaUserGraduate,
  FaCalendarAlt,
  FaSignOutAlt,
  FaGraduationCap,
  FaTasks,
  FaClipboardList,
  FaBrain,
  FaFolderOpen,
  FaClock,
  FaBell,
  FaChartLine,
  FaBars
} from "react-icons/fa";
import "./theme.css";

function MainLayout() {
  const navigate = useNavigate();
  const location = useLocation();

  const userName = localStorage.getItem("user_name");
  const role = localStorage.getItem("role");

  const getInitialTheme = () => {
    const saved = localStorage.getItem("theme_mode");
    if (saved) return saved;
    return "system";
  };

  const [themeMode, setThemeMode] = useState(getInitialTheme());
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 900);

  const applyTheme = (mode) => {
    if (mode === "light") {
      document.documentElement.setAttribute("data-theme", "light");
      return;
    }

    if (mode === "dark") {
      document.documentElement.setAttribute("data-theme", "dark");
      return;
    }

    const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
    document.documentElement.setAttribute("data-theme", prefersDark ? "dark" : "light");
  };

  useEffect(() => {
    applyTheme(themeMode);
    localStorage.setItem("theme_mode", themeMode);
  }, [themeMode]);

  useEffect(() => {
    const media = window.matchMedia("(prefers-color-scheme: dark)");

    const handleSystemThemeChange = () => {
      if (themeMode === "system") {
        applyTheme("system");
      }
    };

    if (media.addEventListener) {
      media.addEventListener("change", handleSystemThemeChange);
    } else {
      media.addListener(handleSystemThemeChange);
    }

    return () => {
      if (media.removeEventListener) {
        media.removeEventListener("change", handleSystemThemeChange);
      } else {
        media.removeListener(handleSystemThemeChange);
      }
    };
  }, [themeMode]);

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 900;
      setIsMobile(mobile);

      if (mobile) {
        setSidebarOpen(false);
      } else {
        setSidebarOpen(true);
      }
    };

    window.addEventListener("resize", handleResize);
    handleResize();

    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  const linkStyle = (path) => {
    const active = location.pathname === path;

  const isDark =
    document.documentElement.getAttribute("data-theme") === "dark";

  return {
    display: "flex",
    alignItems: "center",
    gap: "12px",
    padding: "12px 14px",
    borderRadius: "14px",

    color: active
      ? isDark
        ? "#ffffff"
        : "#1e293b"
      : "var(--text)",

    background: active
      ? isDark
        ? "#ffffff10"
        : "#e2e8f0"
      : "transparent",

    border: active ? "1px solid var(--border)" : "1px solid transparent",

    fontWeight: 700,
    marginBottom: "8px",
    transition: "0.2s"
  };
};

  return (
    <div style={{ display: "flex", minHeight: "100vh" }}>
      <aside
        style={{
          width: isMobile ? "270px" : sidebarOpen ? "280px" : "86px",
          background: "var(--surface)",
          borderRight: "1px solid var(--border)",
          padding: "16px",
          position: isMobile ? "fixed" : "sticky",
          left: isMobile ? (sidebarOpen ? "0" : "-280px") : "0",
          top: 0,
          height: "100vh",
          transition: "0.3s",
          zIndex: 1000,
          display: "flex",
          flexDirection: "column",
          justifyContent: "space-between",
          overflowY: "auto"
        }}
      >
        <div>
          <div
            style={{
              display: "flex",
              justifyContent: sidebarOpen ? "space-between" : "center",
              alignItems: "center",
              marginBottom: "18px"
            }}
          >
            {sidebarOpen ? (
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "10px",
                  fontWeight: 800,
                  color: "var(--text)"
                }}
              >
                <FaGraduationCap />
                <span>LMS Pro</span>
              </div>
            ) : (
              <FaGraduationCap />
            )}

            <button
              className="btn btn-secondary"
              onClick={() => setSidebarOpen(!sidebarOpen)}
            >
              <FaBars />
            </button>
          </div>

          {sidebarOpen && (
            <select
              className="select"
              value={themeMode}
              onChange={(e) => setThemeMode(e.target.value)}
              style={{ marginBottom: "16px" }}
            >
              <option value="system">🖥 System Theme</option>
              <option value="light">☀ Light Theme</option>
              <option value="dark">🌙 Dark Theme</option>
            </select>
          )}

          {role === "teacher" && (
            <Link to="/teacher-dashboard" style={linkStyle("/teacher-dashboard")}>
              <FaChalkboardTeacher />
              {sidebarOpen && "Dashboard"}
            </Link>
          )}

          {role === "student" && (
            <Link to="/student-dashboard" style={linkStyle("/student-dashboard")}>
              <FaUserGraduate />
              {sidebarOpen && "Dashboard"}
            </Link>
          )}

          <Link to="/courses" style={linkStyle("/courses")}>
            <FaBookOpen />
            {sidebarOpen && "Courses"}
          </Link>

          {role === "student" && (
            <>
              <Link to="/planner" style={linkStyle("/planner")}>
                <FaCalendarAlt />
                {sidebarOpen && "Planner"}
              </Link>

              <Link to="/smart-planner" style={linkStyle("/smart-planner")}>
                <FaBrain />
                {sidebarOpen && "Smart Planner"}
              </Link>

              <Link to="/study-tracker" style={linkStyle("/study-tracker")}>
                <FaClock />
                {sidebarOpen && "Study Tracker"}
              </Link>

              <Link to="/reminders" style={linkStyle("/reminders")}>
                <FaBell />
                {sidebarOpen && "Reminders"}
              </Link>

              <Link to="/student-quiz" style={linkStyle("/student-quiz")}>
                <FaTasks />
                {sidebarOpen && "Quiz"}
              </Link>

              <Link
                to="/student-assignments"
                style={linkStyle("/student-assignments")}
              >
                <FaClipboardList />
                {sidebarOpen && "Assignments"}
              </Link>

              <Link to="/materials" style={linkStyle("/materials")}>
                <FaFolderOpen />
                {sidebarOpen && "Materials"}
              </Link>

              <Link to="/pomodoro" style={linkStyle("/pomodoro")}>
                <FaClock />
                {sidebarOpen && "Pomodoro"}
              </Link>
            </>
          )}

          {role === "teacher" && (
            <>
              <Link to="/teacher-quiz" style={linkStyle("/teacher-quiz")}>
                <FaTasks />
                {sidebarOpen && "Quiz"}
              </Link>

              <Link
                to="/teacher-assignments"
                style={linkStyle("/teacher-assignments")}
              >
                <FaClipboardList />
                {sidebarOpen && "Assignments"}
              </Link>

              <Link to="/quiz-analytics" style={linkStyle("/quiz-analytics")}>
                <FaChartLine />
                {sidebarOpen && "Quiz Analytics"}
              </Link>

              <Link to="/upload-material" style={linkStyle("/upload-material")}>
                <FaFolderOpen />
                {sidebarOpen && "Upload"}
              </Link>
            </>
          )}
        </div>
      </aside>

      {isMobile && sidebarOpen && (
        <div
          onClick={() => setSidebarOpen(false)}
          style={{
            position: "fixed",
            top: 0,
            left: 0,
            width: "100%",
            height: "100vh",
            background: "rgba(0,0,0,0.4)",
            zIndex: 999
          }}
        />
      )}

      <main style={{ flex: 1, minWidth: 0 }}>
        <div
          style={{
            background: "var(--surface)",
            padding: "14px 18px",
            borderBottom: "1px solid var(--border)",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            gap: "12px",
            position: "sticky",
            top: 0,
            zIndex: 50
          }}
        >
          <button
            className="btn btn-primary"
            onClick={() => setSidebarOpen(true)}
          >
            <FaBars />
          </button>

          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "12px"
            }}
          >
            <div style={{ fontWeight: 700 }}>
              {userName || "User"}
            </div>

            <button
              className="btn btn-danger"
              onClick={handleLogout}
              style={{
                padding: isMobile ? "6px 10px" : "8px 12px",
                fontSize: isMobile ? "13px" : "14px",
                display: "flex",
                alignItems: "center",
                gap: "6px"
              }}
            >
              <FaSignOutAlt />
              {!isMobile && "Logout"}
            </button>
          </div>
        </div>

        <Outlet />
      </main>
    </div>
  );
}

export default MainLayout;
